#!/bin/bash
# Generated by notebook 02 from run 2026-10-09_qwen3.8-27b_bf16_initial. Runs on the VM from the repo root.
# usage: bash ncu_commands.sh <run_dir> <python>
RUN="$1"; PY="${2:-python}"; CFG="$RUN/config.json"; OUT="$RUN/ncu"; mkdir -p "$OUT"; FAIL=0
SUDO="sudo -E env PATH=$PATH HOME=$HOME HF_HOME=$HOME/.cache/huggingface VLLM_ENABLE_V1_MULTIPROCESSING=0 GMU=0.72 MNS=64"
run() {  # run <name> <ncu args...> : skips reports that already exist (safe to re-run after preemption)
  local name="$1"; shift
  if [ -s "$OUT/$name.ncu-rep" ]; then echo "[skip] $name"; return; fi
  echo "[run ] $name"; $SUDO ncu "$@" -o "$OUT/$name" -f || { echo "[FAIL] $name"; FAIL=$((FAIL+1)); }
}

# 1) Light sweep: every kernel of a short decode range, metrics only (production config: CUDA graphs)
run sweep_b1 --target-processes all --profile-from-start off --graph-profiling node \
  --nvtx --nvtx-include "prefill_decode8_b1/" --metrics gpu__time_duration.sum,dram__bytes_read.sum,dram__bytes_write.sum,dram__throughput.avg.pct_of_peak_sustained_elapsed,sm__throughput.avg.pct_of_peak_sustained_elapsed,launch__grid_size --clock-control none \
  "$PY" scripts/prof_run.py --config "$CFG" --batch 1 --mode graphs --out 8
run sweep_b32 --target-processes all --profile-from-start off --graph-profiling node \
  --nvtx --nvtx-include "prefill_decode8_b32/" --metrics gpu__time_duration.sum,dram__bytes_read.sum,dram__bytes_write.sum,dram__throughput.avg.pct_of_peak_sustained_elapsed,sm__throughput.avg.pct_of_peak_sustained_elapsed,launch__grid_size --clock-control none \
  "$PY" scripts/prof_run.py --config "$CFG" --batch 32 --mode graphs --out 8

